from moler.util.moler_test import MolerTest
from taf.ul.moler.converter.moler_devices import MolerDevices
from moler.config import devices as dev_cfg

import sys
import datetime

_indent_multiplier = 4


def log(msg, level='info'):
    """
    Wrapper for MolerTest logger.

    :param msg: String message
    :param level: info, warning, error
    :return: nothing
    """
    logger = getattr(MolerTest, level)

    if level == 'error':
        logger(msg=msg, raise_exception=True)
    else:
        logger(msg=msg)


def generate_unix_remote_device(device_name, host, login, password):
    md = MolerDevices()
    md.add_remote_unix_configuration(device_name=device_name,
                                     host=host,
                                     login=login,
                                     password=password)

    all_devices = md.get_moler_device_config()['DEVICES']
    device_config = all_devices[device_name]
    _add_device_to_moler_configuration(device_name, device_config)


def generate_unix_local_device(device_name="UnixLocal"):
    md = MolerDevices()
    md.add_local_unix_configuration(device_name=device_name)

    all_devices = md.get_moler_device_config()['DEVICES']
    device_config = all_devices[device_name]
    _add_device_to_moler_configuration(device_name, device_config)


def _add_device_to_moler_configuration(device_name, device_config):
    dev_cfg.define_device(
        name=device_name,
        device_class=device_config['DEVICE_CLASS'],
        connection_desc=device_config.get('CONNECTION_DESC', dev_cfg.default_connection),
        connection_hops={'CONNECTION_HOPS': device_config.get('CONNECTION_HOPS', {})},
        initial_state=device_config.get('INITIAL_STATE', None),
    )


def _get_robot_context():
    try:
        from robot.running.context import EXECUTION_CONTEXTS
        return EXECUTION_CONTEXTS.current
    except Exception:
        pass
    return None


def is_dry_run():
    try:
        current_context = _get_robot_context()
        if current_context.dry_run:
            return True
    except Exception:
        pass
    return False


def log_info_to_console(msg, log_hierarchy=1, add_timestamp=True, add_new_line=True, add_carriage_return=True):
    """
    Print formatted logs on the console.

    :param msg: str,
    :param log_hierarchy: int, determine how deep should be indent,
    :param add_timestamp: bool.
    :param add_new_line: bool, Add new line sign at te end of msg
    :param add_carriage_return: bool, Add carriage return sign at te begin of msg
    :return: None
    """
    indent = ' ' * _indent_multiplier * log_hierarchy if log_hierarchy else ''
    full_msg = ''
    if add_timestamp:
        msg_time = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        full_msg = "[{}]".format(msg_time)
    full_msg = "{}{}{}".format(full_msg, indent, msg)
    full_msg = "\r{}".format(full_msg) if add_carriage_return else full_msg
    full_msg = "{}\n".format(full_msg) if add_new_line else full_msg
    sys.__stdout__.write('{}'.format(full_msg))
